import {Post} from "./Post";
import wip from "./assets/hana.png";

export const WipPost = (
  <Post imgSrc={wip} imgAlt={"wip image"} imgCover={true}
        title={"wip: my custom game engine"} date={"may 5, 2024"}
        id={"wip"}>
    <p>
      You might think I haven't given this engine a name yet. But you'd be wrong!
      The name <i>is</i> <b>wip</b>, and that's for good reason. I've started
      projects many times because I came up with a cool name for them. But as
      soon as I start a project like that, the project's doomed, because I'm
      hyped for the cool name, not for what the project actually is. 
    </p>
  </Post>
)
